package com.enfec.one.asset.notification;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="notifications") public class Notification { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=100) private String username; @Column(nullable=false,length=200) private String title; @Column(nullable=false,length=1000) private String message; @Column(nullable=false) private boolean readFlag; @Column(nullable=false) private OffsetDateTime createdAt; protected Notification(){} public Notification(String u,String t,String m){username=u;title=t;message=m;readFlag=false;createdAt=OffsetDateTime.now(ZoneOffset.UTC);} public UUID getId(){return id;} public String getUsername(){return username;} public String getTitle(){return title;} public String getMessage(){return message;} public boolean isReadFlag(){return readFlag;} public OffsetDateTime getCreatedAt(){return createdAt;} public void markRead(){readFlag=true;}}
